<span class="line"><span style="color:#D19A66;">  -p</span><span style="color:#98C379;"> 6379:6379</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> 8001:8001</span><span style="color:#56B6C2;"> \\</span></span>
